const $=s=>document.querySelector(s);
const titles=['Aprender','Entender','Praticar','Desafio final'];
let stage=0,mode='practice',cursor=0,selected=null,answers=[],element='raio',example=0;
const fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n);
const basics='Circunferência é o contorno: seus pontos estão à mesma distância do centro. Círculo inclui o contorno e o interior. Esfera é um corpo tridimensional. Raio liga centro e contorno; corda liga dois pontos do contorno; diâmetro é a corda que passa pelo centro. d = 2r. Para o comprimento: C = πd = 2πr. Use o valor de π indicado na questão.';
function shape(type){return `<svg class="diagram" viewBox="0 0 200 150" role="img" aria-label="${type==='ring'?'Circunferência: apenas o contorno':type==='disk'?'Círculo: contorno e interior':'Esfera: corpo com três dimensões'}"><defs><radialGradient id="ball"><stop offset="0" stop-color="#c7f7e7"/><stop offset=".6" stop-color="#65c9a4"/><stop offset="1" stop-color="#279473"/></radialGradient></defs><circle cx="100" cy="75" r="53" fill="${type==='ring'?'none':type==='disk'?'#f4b752':'url(#ball)'}" stroke="${type==='ring'?'#9672da':type==='disk'?'#df9f37':'#369e7e'}" stroke-width="4"/>${type==='ball'?'<ellipse cx="100" cy="75" rx="52" ry="17" fill="none" stroke="#237b61" stroke-dasharray="5 5" opacity=".6"/>':'<circle cx="100" cy="75" r="3" fill="#51406e"/><text x="109" y="91" font-size="13" fill="#51406e">O</text>'}</svg>`}
const heroArt=`<svg class="hero-art" viewBox="0 0 240 210" aria-hidden="true"><ellipse cx="125" cy="116" rx="108" ry="40" transform="rotate(-25 125 116)" fill="none" stroke="#aa95d9" stroke-width="2"/><circle cx="128" cy="95" r="62" fill="#7353bf"/><circle cx="108" cy="77" r="42" fill="#8d6dcf"/><circle cx="87" cy="66" r="15" fill="#aa8de0"/><ellipse cx="125" cy="116" rx="108" ry="40" transform="rotate(-25 125 116)" fill="none" stroke="#d2bbfb" stroke-width="9" stroke-dasharray="260 290"/><circle cx="199" cy="45" r="15" fill="#f7b94f"/><path d="M35 35v20m-10-10h20M198 158v16m-8-8h16" stroke="#8b6ec4" stroke-width="3"/><circle cx="40" cy="172" r="5" fill="#efab42"/></svg>`;
function hero(kicker,title,desc){return `<section class="hero"><div><span class="pill">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${heroArt}</section>`}
function navigate(n){stage=n;render();$('#main').focus();window.scrollTo({top:0,behavior:'instant'})}
function render(){ $('#nav').innerHTML=titles.map((t,i)=>`<button data-stage="${i}" class="${stage===i?'active':''}" ${stage===i?'aria-current="step"':''}><span class="num">${i+1}</span><span>${t}<small>${['Descubra as formas','Conecte as ideias','Experimente sem pressa','Sua missão de hoje'][i]}</small></span></button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(+b.dataset.stage>=2&&stage!==+b.dataset.stage)reset(+b.dataset.stage===2?'practice':'final');navigate(+b.dataset.stage)});if(stage===0)learn();if(stage===1)understand();if(stage>=2)quiz(); }
function originalLearn(){ $('#main').innerHTML=hero('MISSÃO 01 · EXPLORAR','Um universo de formas.<br>Vamos dar uma volta?','Da roda da bicicleta à bola de tênis: descubra a matemática que está ao seu redor.')+`<div class="section-top"><h2>Parecidas, mas diferentes</h2><span>Três formas. Três ideias.</span></div><div class="cards">${[['ring','SÓ O CONTORNO','Circunferência','Pense no aro de metal. Todos os pontos do contorno estão à mesma distância do centro.'],['disk','CONTORNO + INTERIOR','Círculo','Pense na face de uma placa redonda de madeira. É uma região plana, preenchida.'],['ball','TRÊS DIMENSÕES','Esfera','Pense em uma bola de tênis. É um corpo arredondado que ocupa espaço.']].map(([s,t,h,p])=>`<article class="card">${shape(s)}<span class="tag">${t}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="tip">💡 <b>Guarde esta ideia:</b> aro → contorno; placa → região plana; bola → corpo no espaço.</div><section class="panel"><div class="section-top" style="margin-top:0"><h2>Explore por dentro</h2><span>Toque nos elementos</span></div><div class="lab"><div id="element-drawing"></div><div><div class="controls">${['raio','corda','diâmetro'].map(t=>`<button class="chip" data-element="${t}">${t}</button>`).join('')}</div><h3 id="element-title"></h3><p id="element-copy"></p><p class="formula">d = 2 × r &nbsp; · &nbsp; r = d ÷ 2</p><p class="small">Todo diâmetro é uma corda. Nem toda corda é um diâmetro.</p></div></div></section><section class="panel"><h2>Mais descobertas</h2><details><summary>O que é um lugar geométrico?</summary><p>É um conjunto de pontos que satisfazem uma propriedade. Na circunferência, todos estão exatamente à distância r do centro. No círculo, estão a uma distância menor ou igual a r, incluindo o centro e a borda.</p><p>Com o compasso aberto em 5 cm, marque o centro O e gire uma volta completa. Você traça uma circunferência de raio 5 cm. Qualquer ponto a 5 cm de O pertence a ela.</p></details><details><summary>Como medir uma volta completa?</summary><p>O comprimento C é a medida do contorno. Dividindo C pelo diâmetro d, obtemos sempre π (pi), aproximadamente 3,14.</p><p class="formula">C = π × d = 2 × π × r</p><p>π = 3,14159265… tem infinitas casas decimais não periódicas e não é racional. Use π ≈ 3,14 nos cálculos, exceto quando o exercício indicar outra aproximação.</p></details><details><summary>Como Arquimedes se aproximou de π?</summary><p>Um hexágono regular inscrito tem seis lados iguais ao raio: seu perímetro é 6r. Dividindo por 2r, obtemos 3. O contorno da circunferência é um pouco maior.</p><p>Arquimedes usou polígonos dentro e fora da circunferência. Com 6, 12, 24 e até 96 lados, seus perímetros ficaram cada vez mais próximos do contorno. As aproximações 223/71 ≈ 3,1408 e 22/7 ≈ 3,1428 ajudam a entender por que usamos 3,14.</p></details><details><summary>E quando duas circunferências têm o mesmo centro?</summary><p>Elas são concêntricas. Podem ter raios diferentes e compartilhar o mesmo centro, como na observação artística proposta na página 8 do PDF.</p></details></section><div class="end-row"><span class="small">Sem cronômetro. Aprenda no seu ritmo.</span><button class="primary" id="next-stage">Entender com exemplos →</button></div>`;document.querySelectorAll('[data-element]').forEach(b=>b.onclick=()=>{element=b.dataset.element;drawElement()});drawElement();$('#next-stage').onclick=()=>navigate(1);}
function drawElement(){const data={raio:['Do centro até a borda','O raio liga o centro O a um ponto da circunferência. Todos os raios de uma mesma circunferência têm a mesma medida.','<line x1="120" y1="110" x2="200" y2="110" stroke="#6e48c5" stroke-width="5"/><text x="154" y="98">r</text>'],corda:['De uma borda à outra','A corda liga dois pontos da circunferência. Ela pode passar pelo centro ou não.','<line x1="56" y1="62" x2="184" y2="62" stroke="#dc8b27" stroke-width="5"/><text x="98" y="48">corda</text>'],'diâmetro':['Dois raios em uma linha','O diâmetro liga dois pontos da circunferência e passa pelo centro. É a maior corda e mede o dobro do raio.','<line x1="40" y1="110" x2="200" y2="110" stroke="#2a9c80" stroke-width="5"/><text x="115" y="95">d</text>']};const d=data[element];$('#element-title').textContent=d[0];$('#element-copy').textContent=d[1];$('#element-drawing').innerHTML=`<svg viewBox="0 0 240 220" role="img" aria-label="Representação do elemento ${element}"><circle cx="120" cy="110" r="80" fill="#f6f2ff" stroke="#b7a3de" stroke-width="3"/>${d[2]}<circle cx="120" cy="110" r="4" fill="#372454"/><text x="117" y="131" font-size="14">O</text></svg>`;document.querySelectorAll('[data-element]').forEach(b=>{b.classList.toggle('selected',b.dataset.element===element);b.setAttribute('aria-pressed',b.dataset.element===element)})}
const examples=[{title:'Compasso: todos os raios são iguais',source:'PDF p. 4 · Livro p. 71',steps:['Marque O e abra o compasso em 5 cm. Essa abertura é o raio.','Gire o compasso sem mudar a abertura. A figura traçada é uma circunferência.','Marque A, B, C, D e E no contorno. OA = OB = OC = OD = OE = 5 cm.','Um ponto F a exatamente 5 cm de O também pertence à circunferência.'],result:'Raio: 5 cm · Diâmetro: 10 cm'}, {title:'Caminhada na praça: 15 voltas',source:'PDF p. 7 · Atividade 5 · Use π ≈ 3',steps:['O raio da praça é 50 m. Queremos a distância em 15 voltas.','Calcule uma volta: C = 2 × π × r = 2 × 3 × 50 = 300 m.','Multiplique pelo número de voltas: 15 × 300 = 4.500 m.','Converta para quilômetros: 4.500 ÷ 1.000 = 4,50 km.'],result:'Distância total: 4,50 km'}, {title:'Duas pistas, distâncias diferentes',source:'PDF p. 8 · Atividade 6 · Use π ≈ 3,14',steps:['A pista interna tem raio de 70 m; a externa, de 80 m.','Volta interna: 2 × 3,14 × 70 = 439,6 m.','Volta externa: 2 × 3,14 × 80 = 502,4 m.','Subtraia: 502,4 − 439,6 = 62,8 m. Essa é a diferença para uma volta completa.'],result:'Diferença entre as largadas: 62,8 m'}];
function originalUnderstand(){const e=examples[example];$('#main').innerHTML=hero('MISSÃO 02 · CONECTAR','Cada problema tem<br>um caminho.','Veja o raciocínio passo a passo. Entender o caminho vale mais do que decorar a resposta.')+`<div class="panel"><div class="controls">${examples.map((e,i)=>`<button class="chip ${i===example?'selected':''}" data-example="${i}" aria-pressed="${i===example}">${['Compasso','Caminhada','Pistas'][i]}</button>`).join('')}</div><p class="eyebrow">${e.source}</p><h2>${e.title}</h2><ol class="steps">${e.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="tip"><b>${e.result}</b></div></div><section class="panel"><h2>Laboratório de uma volta</h2><p>Altere o raio e observe o diâmetro e o comprimento. Aqui, usamos π ≈ 3,14.</p><div class="lab"><div id="lab-picture"></div><div><label for="radius">Raio: <b id="r-label"></b> cm</label><input class="range" id="radius" type="range" min="1" max="20" value="5"><p id="lab-formula" class="formula"></p><p id="lab-calc"></p><p class="small">O desenho é ilustrativo, sem escala física em centímetros.</p></div></div></section><section class="panel"><h2>Ateliê de ideias</h2><details><summary>Desenhar com compasso · atividades 1 e 8</summary><p>No papel, desenhe circunferências de raios 5 cm, 72 mm e 0,06 m. Para usar a régua em centímetros: 72 mm = 7,2 cm e 0,06 m = 6 cm.</p><p>Na atividade 8, observe o azulejo e reproduza-o em uma malha quadriculada usando instrumentos de desenho. Abra a página original para ver o modelo.</p><button class="secondary" data-page="8">Ver o azulejo da página 8</button></details><details><summary>Pescadores e uma região ao redor · atividades 2 e 3</summary><p>Se os peixes ficam à mesma distância da fogueira, suas posições formam uma circunferência e o fogo ocupa o centro.</p><p>Na ilustração da atividade 3, o círculo representa a região ao redor de cada pessoa. A borda marca uma distância fixa e o interior reúne os pontos mais próximos. Esta é uma leitura geométrica da imagem histórica do livro.</p></details><details><summary>Investigar as cordas · atividade 4</summary><p>Na figura original, AE e BF são as maiores cordas: ambas passam por O e são diâmetros. Nenhuma corda é maior que o diâmetro.</p><p>Meça AE, CE, BE, BF, CG e DF com uma régua no material impresso. Não use centímetros da tela: o tamanho varia com o dispositivo e o zoom. As medidas dependem da escala da impressão; compare principalmente as relações entre os segmentos.</p><button class="secondary" data-page="7">Ver a figura das cordas</button></details><details><summary>Arte com circunferências · atividade 7</summary><p>Na obra de Kandinsky aparecem círculos, circunferências e segmentos de reta. Circunferências de raios diferentes com o mesmo centro são concêntricas.</p><p>Crie sua composição abaixo: escolha raio e cor, depois toque na área para colocar uma circunferência. Você também pode usar o botão para colocar uma no centro.</p><label>Raio do traço <input type="range" id="art-radius" min="15" max="100" value="45"></label> <label>Cor <input id="art-color" type="color" value="#7852bf"></label><svg id="artboard" class="artboard" viewBox="0 0 600 320" role="img" aria-label="Sua composição de circunferências"></svg><div class="actions"><button class="secondary" id="add-ring">Adicionar no centro</button><button class="secondary" id="clear-art">Limpar composição</button><button class="secondary" data-page="8">Ver a obra e o azulejo</button></div></details></section><div class="end-row"><button class="text-button" id="back-learn">← Revisar explicações</button><button class="primary" id="to-practice">Vamos praticar →</button></div>`;document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{example=+b.dataset.example;understand()});$('#radius').oninput=updateLab;updateLab();$('#back-learn').onclick=()=>navigate(0);$('#to-practice').onclick=()=>{reset('practice');navigate(2)};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showMaterial(+b.dataset.page));const add=(x,y)=>{$('#artboard').insertAdjacentHTML('beforeend',`<circle cx="${x}" cy="${y}" r="${$('#art-radius').value}" fill="none" stroke="${$('#art-color').value}" stroke-width="3"/>`)};$('#artboard').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();add((e.clientX-r.left)*600/r.width,(e.clientY-r.top)*320/r.height)};$('#add-ring').onclick=()=>add(300,160);$('#clear-art').onclick=()=>$('#artboard').innerHTML='';}
function updateLab(){const r=+$('#radius').value;$('#r-label').textContent=r;$('#lab-formula').textContent=`d = 2 × ${r} = ${2*r} cm`;$('#lab-calc').textContent=`C = 2 × 3,14 × ${r} ≈ ${fmt(6.28*r)} cm`;$('#lab-picture').innerHTML=`<svg viewBox="0 0 220 220" role="img" aria-label="Circunferência de raio ${r} centímetros"><circle cx="110" cy="110" r="${30+3*r}" fill="#f1ebfc" stroke="#8056cb" stroke-width="3"/><line x1="110" y1="110" x2="${140+3*r}" y2="110" stroke="#e7a12e" stroke-width="4"/><circle cx="110" cy="110" r="3"/><text x="110" y="135" text-anchor="middle">r = ${r} cm</text></svg>`}
const Q=(q,options,a,explanation,topic)=>({q,options,a,explanation,topic});
const practice=[
Q('Qual objeto ajuda a representar uma esfera?',['Aro de metal','Bola de tênis','Face plana de uma placa'],1,'A bola ocupa espaço e tem três dimensões. O aro lembra a circunferência e a face da placa lembra o círculo.','As três formas'),
Q('Uma circunferência tem raio de 5 cm. Quanto mede seu diâmetro?',['2,5 cm','5 cm','10 cm'],2,'O diâmetro é formado por dois raios: d = 2 × 5 = 10 cm.','Raio e diâmetro'),
Q('O compasso está aberto em 5 cm. Um ponto F está a 5 cm do centro. Onde ele está?',['Na circunferência','Somente fora do círculo','No centro'],0,'Todos os pontos a exatamente 5 cm do centro pertencem à circunferência de raio 5 cm.','Lugar geométrico'),
Q('Uma corda passa pelo centro. Qual nome especial ela recebe?',['Raio','Diâmetro','Esfera'],1,'O diâmetro é uma corda que passa pelo centro. Suas duas extremidades estão na circunferência.','Cordas'),
Q('Como ficam os peixes colocados à mesma distância da fogueira?',['Em posições de uma circunferência','Todos no centro','Em qualquer ponto do interior'],0,'A fogueira é o centro. A distância fixa define uma circunferência, como na atividade 2 do material.','Lugar geométrico'),
Q('Na praça de raio 50 m, qual é a distância de 15 voltas? Use π ≈ 3.',['0,30 km','2,25 km','4,50 km'],2,'Uma volta: 2 × 3 × 50 = 300 m. Quinze voltas: 4.500 m = 4,50 km.','Comprimento'),
Q('Duas pistas circulares têm raios de 70 m e 80 m. Qual é a diferença de uma volta? Use π ≈ 3,14.',['10 m','62,8 m','502,4 m'],1,'Os comprimentos são 439,6 m e 502,4 m. A diferença é 502,4 − 439,6 = 62,8 m.','Comprimento'),
Q('Circunferências com o mesmo centro e raios diferentes são…',['Concêntricas','Diâmetros','Esferas'],0,'Concêntricas significa que compartilham o mesmo centro. Isso não exige raios iguais.','Arte e geometria')];
const finalQuestions=[
Q('Qual descrição corresponde ao círculo?',['Apenas o contorno','O contorno e todos os pontos do interior','Um corpo com três dimensões'],1,'O círculo é a região plana formada pela circunferência e por seu interior.','As três formas'),
Q('Qual figura é tridimensional?',['Circunferência','Círculo','Esfera'],2,'A esfera é um corpo que ocupa espaço, como uma bola.','As três formas'),
Q('O segmento que une o centro a um ponto da circunferência é o…',['Raio','Diâmetro','Contorno'],0,'O raio tem uma extremidade no centro e a outra na circunferência.','Raio e diâmetro'),
Q('Uma circunferência tem diâmetro de 10 cm. Seu raio mede…',['20 cm','10 cm','5 cm'],2,'O raio é metade do diâmetro: r = 10 ÷ 2 = 5 cm.','Raio e diâmetro'),
Q('Qual afirmação sobre cordas é verdadeira?',['Todas passam pelo centro','O diâmetro é a maior corda','Uma corda pode ser maior que o diâmetro'],1,'O diâmetro liga dois pontos do contorno passando pelo centro. Nenhuma corda dessa circunferência é maior que ele.','Cordas'),
Q('No círculo de raio 5 cm, quais pontos fazem parte da região?',['Só os que estão a 5 cm do centro','Os que estão a uma distância menor ou igual a 5 cm do centro','Só os que estão além de 5 cm'],1,'O círculo inclui a borda e o interior: a distância até o centro pode ser menor ou igual ao raio.','Lugar geométrico'),
Q('Ao dividir o comprimento da circunferência pelo diâmetro, obtemos…',['π, aproximadamente 3,14','Sempre 2','O raio'],0,'C ÷ d = π. Por isso, C = π × d. A razão é a mesma para qualquer circunferência.','O número π'),
Q('Qual é a distância de 15 voltas em uma praça de raio 50 m? Use π ≈ 3.',['4,50 km','1,50 km','0,75 km'],0,'C = 2 × 3 × 50 = 300 m por volta. 15 × 300 = 4.500 m = 4,50 km.','Comprimento'),
Q('Qual é a diferença entre uma volta de raio 80 m e outra de raio 70 m? Use π ≈ 3,14.',['31,4 m','10 m','62,8 m'],2,'2 × 3,14 × 80 − 2 × 3,14 × 70 = 502,4 − 439,6 = 62,8 m.','Comprimento'),
Q('Duas circunferências concêntricas têm necessariamente…',['O mesmo raio','O mesmo centro','O mesmo comprimento'],1,'Elas compartilham o centro e podem ter raios e comprimentos diferentes.','Arte e geometria')];
function reset(m){mode=m;cursor=0;selected=null;answers=[]}
function questions(){return mode==='final'?finalQuestions:practice}
function originalQuiz(){const qs=questions();if(cursor>=qs.length){result();return}const q=qs[cursor],record=answers[cursor],done=answers.length,correct=answers.filter(a=>a.correct).length;$('#main').innerHTML=hero(mode==='final'?'MISSÃO 04 · CONQUISTAR':'MISSÃO 03 · EXPERIMENTAR',mode==='final'?'Seu desafio final.':'Agora é com você.',mode==='final'?`${questions().length} questões, uma conquista de cada vez. Você pode revisar antes de responder.`:'O erro é uma pista para aprender. Leia, escolha e descubra o porquê de cada resposta.')+`<section class="panel"><div class="quiz-top"><b>Questão ${cursor+1} de ${qs.length}</b><span class="small">${done} respondidas · ${correct} acertos</span></div><div class="progress" role="progressbar" aria-label="Progresso das respostas" aria-valuemin="0" aria-valuemax="${qs.length}" aria-valuenow="${done}"><span style="width:${done/qs.length*100}%"></span></div><span class="eyebrow">${q.topic}</span><h2 class="question">${q.q}</h2><button class="text-button" id="review-before">↗ Revisar antes de responder</button><div class="options" role="group" aria-label="Alternativas">${q.options.map((s,i)=>`<button class="option ${selected===i?'chosen':''} ${record?(i===q.a?'good':i===record.choice?'bad':''):''}" data-choice="${i}" aria-pressed="${selected===i}" ${record?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${s}${record&&i===q.a?' ✓':''}</button>`).join('')}</div>${record?`<div class="feedback ${record.correct?'':'wrong'}" role="status"><b>${record.correct?'✓ Muito bem! Você acertou.':'↻ Vamos entender juntas.'}</b><p>${q.explanation}</p></div>`:''}<div class="actions"><button class="primary" id="confirm" ${selected===null?'disabled':''}>${record?(cursor===qs.length-1?'Ver meu resultado →':'Próxima questão →'):'Confirmar resposta'}</button><button class="text-button" id="restart">Recomeçar esta etapa</button></div><p class="small">Pontuação da etapa: ${correct}/${qs.length} × 100 = ${fmt(correct/qs.length*100)}%. Questões ainda não respondidas não são erros.</p></section>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{selected=+b.dataset.choice;quiz();$(`[data-choice="${selected}"]`).focus()});$('#confirm').onclick=()=>{if(record){cursor++;selected=null;quiz();$('#main').focus()}else if(selected!==null){answers.push({choice:selected,correct:selected===q.a});quiz();$('#confirm').focus()}};$('#review-before').onclick=()=>openDialog(`<h2>Uma pausa para revisar</h2><p>${basics}</p><div class="tip"><b>Para resolver:</b> identifique se a medida dada é raio ou diâmetro; escolha a fórmula; substitua os valores; confira a unidade. Em várias voltas, multiplique o comprimento pelo número de voltas.</div><p>A praça usa π ≈ 3. A comparação das pistas usa π ≈ 3,14.</p><p class="small">Feche esta janela para continuar exatamente de onde parou.</p>`);$('#restart').onclick=()=>{reset(mode);quiz()};}
function originalResult(){const qs=questions(),correct=answers.filter(a=>a.correct).length,wrong=qs.length-correct,pct=correct/qs.length*100;const message=pct>=90?'🎉 PARABÉNS! Você arrasou! Seu desempenho foi incrível! Continue assim, você está dominando a matemática!':pct>=80?'Muito bem! Você construiu uma ótima base. Revise as questões que faltaram e siga avançando!':'Cada tentativa ajuda você a aprender. Vamos revisar as ideias que ainda precisam de atenção e tentar novamente?';$('#main').innerHTML=`<section class="panel result"><span class="pill">${mode==='final'?'DESAFIO CONCLUÍDO':'PRÁTICA CONCLUÍDA'}</span><div class="badge" aria-hidden="true">${pct>=90?'🏆':pct>=80?'🌟':'🌱'}</div><h1>${pct>=90?'Uma conquista para comemorar!':pct>=80?'Você está no caminho!':'Sua jornada continua!'}</h1><div class="score">${fmt(pct)}%</div><p>${message}</p>${pct===100?'<div class="tip"><b>100%: você acertou TODAS as questões!</b></div>':''}<div class="stats"><div><strong>${correct}</strong>acertos</div><div><strong>${wrong}</strong>erros</div><div><strong>${qs.length}</strong>questões</div></div><p class="small">${correct} ÷ ${qs.length} × 100 = ${fmt(pct)}%</p><div class="actions" style="justify-content:center"><button class="primary" id="show-review">Revisar respostas</button><button class="secondary" id="retry">Refazer exercícios</button><button class="secondary" id="next-result">${mode==='practice'?'Ir ao desafio final →':'Revisar explicações'}</button></div></section><section class="panel" id="answer-review" hidden><h2>Seu mapa de aprendizagem</h2><p>${wrong?`Vale revisar: ${[...new Set(qs.filter((q,i)=>!answers[i].correct).map(q=>q.topic))].join(', ')}.`:'Todas as ideias desta etapa foram respondidas corretamente.'}</p>${qs.map((q,i)=>`<article class="review-row"><b>${answers[i].correct?'✓ Acerto':'↻ Para revisar'} · ${i+1}. ${q.q}</b><p>Sua resposta: ${q.options[answers[i].choice]}</p>${answers[i].correct?'':`<p><b>Resposta correta: ${q.options[q.a]}</b></p>`}<p>${q.explanation}</p></article>`).join('')}</section>`;$('#show-review').onclick=()=>{$('#answer-review').hidden=false;$('#answer-review').scrollIntoView({behavior:'smooth'})};$('#retry').onclick=()=>{reset(mode);quiz()};$('#next-result').onclick=()=>{if(mode==='practice'){reset('final');navigate(3)}else navigate(0)};if(pct>=90)celebrate();}
let celebrationTimer=0;
function celebrate(){
  clearTimeout(celebrationTimer);
  const colors=['#8b5cf6','#ff477e','#ffbd20','#20c997','#21a5ff','#ff762e','#e34cff','#20c6cf'];
  $('#confetti').innerHTML=Array.from({length:240},(_,i)=>{
    const duration=3.8+Math.random()*1.4;
    // A primeira onda já ocupa a altura da tela; as outras continuam caindo do topo.
    const delay=i<96?-Math.random()*duration*.8:Math.random()*1.6;
    return `<i style="left:${(i+.15+Math.random()*.7)/240*100}%;background:${colors[i%colors.length]};width:${7+Math.random()*6}px;height:${i%4===0?10:15+Math.random()*7}px;border-radius:${i%4===0?'50%':'2px'};--still-top:${Math.random()*97}%;--drift:${(Math.random()-.5)*100}px;--spin:${Math.random()>.5?720:-720}deg;animation-duration:${duration}s;animation-delay:${delay}s"></i>`;
  }).join('');
  celebrationTimer=setTimeout(()=>{$('#confetti').innerHTML='';celebrationTimer=0},7200);
}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function originalShowMaterial(page=1){openDialog(`<h2>Seu material de referência</h2><p>Somente as páginas 1 a 8 do PDF (68 a 75 do livro).</p><label for="page-select">Escolha uma página </label><select id="page-select">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${page===i+1?'selected':''}>PDF ${i+1} · Livro ${68+i}</option>`).join('')}</select><p class="small">As páginas são imagens do arquivo original. As explicações e atividades da plataforma apresentam o conteúdo em texto acessível.</p><img class="page-image" src="material/pagina-0${page}.png" alt="Página ${page} do PDF, página ${67+page} do livro de Matemática">`);$('#page-select').onchange=e=>showMaterial(+e.target.value)}
$('#material').onclick=()=>showMaterial();$('.close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
